config.script:
try:
	system.perspective.closePopup('dataItemSelector')
except:
	pass

self.params.values.chkShtId = None

return

transforms.code:
timerUpdate = self.custom.timerUpdate or system.date.now()	
if value['selected'] and value['display']:

	if system.date.secondsBetween(timerUpdate, value['timeNow']) > 300  and not self.view.custom.infoBar.showBar: 
		system.perspective.sendMessage('getMatrixTableData', {})
		timerUpdate = value['timeNow']

return timerUpdate

messageHandlers.script:
system.perspective.print('confirmCancel() msg rcvd with %s'%payload)

self.view.custom.infoBar = {"showBar": False, "text": "", "type": "INFO"}

return


system.perspective.print("assetSelected() msg rcvd by chkShtDetail with %s"%payload)
try:
	self.view.custom.filters.assetPath = payload['selection'][0]['path'] if len(payload['selection']) > 0 else None
except:
	pass		

return

system.perspective.print("itemSelected() msg rcvd by chkShtDetails with %s"%payload)

items = []
itemClasses = []

for entry in payload['selection']:
	if entry['value'].has_key('itemId'): items.append({'itemPath':entry['value']['path'], 'itemId': entry['value']['itemId']})
	else: itemClasses.append({'itemClassPath':entry['value']['path'], 'itemClassId': system.kanoa.utilities.getFieldValue('itemClassId', system.kanoa.item.getItemClasses({'itemClassPath' :entry['value']['path']}))})

self.view.custom.filters.items = items
self.view.custom.filters.itemClasses = itemClasses

return
